// 18-tap FIR, TRANSFERENTITY form (feedforward, register-less, named
// transfer function -> direct form) -> minimal register count. Same transfer
// function as the one-tap FIR stage linked to all the others (feedback,
// register-full, inline transfer function) -> identical register-to-register
// delay to the reference one-tap FIR -> identical pipeline delay to the
// register-less direct form.
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; y <= 16'd0;
        end else begin
            a0 <= 8'd2 * x + 3 + 24'd14041;
            a1 <= 8'd4 * a0[7:0] + 3 + 24'd13998;
            a2 <= 8'd6 * a1[7:0] + 3 + 24'd13956;
            a3 <= 8'd8 * a2[7:0] + 3 + 24'd13915;
            a4 <= 8'd10 * a3[7:0] + 3 + 24'd13875;
            a5 <= 8'd12 * a4[7:0] + 3 + 24'd13835;
            a6 <= 8'd14 * a5[7:0] + 3 + 24'd13796;
            a7 <= 8'd16 * a6[7:0] + 3 + 24'd13758;
            a8 <= 8'd18 * a7[7:0] + 3 + 24'd13720;
            a9 <= 8'd20 * a8[7:0] + 3 + 24'd13683;
            a10 <= 8'd22 * a9[7:0] + 3 + 24'd13647;
            a11 <= 8'd24 * a10[7:0] + 3 + 24'd13611;
            a12 <= 8'd26 * a11[7:0] + 3 + 24'd13576;
            a13 <= 8'd28 * a12[7:0] + 3 + 24'd13542;
            a14 <= 8'd30 * a13[7:0] + 3 + 24'd13508;
            a15 <= 8'd32 * a14[7:0] + 3 + 24'd13475;
            a16 <= 8'd34 * a15[7:0] + 3 + 24'd13442;
            a17 <= 8'd36 * a16[7:0] + 3 + 24'd13410;
            y <= a17[15:0];
        end
    end
endmodule
